import * as ChildProcess from "effect/process/ChildProcess";
export function launch(executable: string, entry: string, cwd: string, isBun: boolean): unknown {
  const args = [...(isBun ? ["run"] : ["--experimental-transform-types", "--no-warnings=ExperimentalWarning"]), entry, JSON.stringify({ ready: true })];
  return ChildProcess.make(executable, args, { cwd, stdin: "ignore" });
}

import * as NodeChildProcess from "node:child_process";
export function launch(executable: string, entry: string, cwd: string, isBun: boolean): unknown {
  const args = [...(isBun ? ["run"] : []), entry, JSON.stringify({ ready: true })];
  return NodeChildProcess.spawn(executable, args, { cwd, stdio: "inherit" });
}
